open = [start]
came_from = {}
g = {start: 0}
while open:
    cur = min(open, key=lambda n: g[n] + h(n, goal))
    if cur == goal: return reconstruct(came_from, cur)
    open.remove(cur)
    for nb in neighbors(cur):
        ng = g[cur] + cost(cur, nb)
